<script setup lang="ts">
import {ref,reactive,computed,onMounted,watch} from 'vue'
import {useRoute} from 'vue-router'
import {ElMessage,ElMessageBox,type FormInstance} from 'element-plus'
import {api,post,download,type RecordRow,type AIJob,type User} from '../api'
import {landRules,growthRules,environmentRules,analysisRules,confirmRules,feedbackRules} from '../flow-schema'
const props=defineProps<{user:User}>()
const route=useRoute()
type Weather={source:string;fetched_at:string;cached:boolean;latitude:number;longitude:number;current:{temperature_2m:number;relative_humidity_2m:number;precipitation:number;wind_speed_10m:number;time:string}}
type Flow={land:RecordRow;growth:RecordRow[];environment:RecordRow[];tasks:RecordRow[];jobs:AIJob[]}
const lands=ref<RecordRow[]>([]),plotId=ref<number>(),flow=ref<Flow>(),weather=ref<Weather>(),weatherError=ref(''),weatherBusy=ref(false),busy=ref(false),saving=ref(false),dialog=ref(''),error=ref(''),formRef=ref<FormInstance>(),selected=ref<AIJob>(),editingTask=ref<RecordRow>(),editingLand=ref<RecordRow>(),fileInput=ref<HTMLInputElement>(),activeTab=ref('growth')
const today=()=>new Date().toLocaleDateString('sv-SE')
const land=reactive({title:'',crop:'',latitude:undefined as number|undefined,longitude:undefined as number|undefined})
const growth=reactive({title:'',crop:'',variety:'',sow_date:'',stage:'营养生长期',harvest_date:'',height:undefined as number|undefined,note:''})
const environment=reactive({temperature:undefined as number|undefined,humidity:undefined as number|undefined,soil:undefined as number|undefined,source:'人工记录',note:''})
const analysis=reactive({question:'',growth_id:undefined as number|undefined,image:''}),analysisRef=ref<FormInstance>()
const confirmation=reactive({title:'',assignee:'',date:today(),note:''}),feedback=reactive({note:''})
const currentGrowth=computed(()=>flow.value?.growth.find(r=>r.id===analysis.growth_id))
const latestEnvironment=computed(()=>flow.value?.environment.at(-1))
const progress=computed(()=>!plotId.value?0:!flow.value?.growth.length?1:!flow.value?.environment.length?2:!flow.value?.jobs.length?3:!flow.value?.tasks.length?4:flow.value.tasks.some(t=>t.status==='已完成')?6:5)
const rules=computed(()=>dialog.value==='land'?landRules:dialog.value==='growth'?growthRules:dialog.value==='environment'?environmentRules:dialog.value==='confirm'?confirmRules:feedbackRules)
const model=computed(()=>dialog.value==='land'?land:dialog.value==='growth'?growth:dialog.value==='environment'?environment:dialog.value==='confirm'?confirmation:feedback)
const dialogTitle=computed(()=>({land:editingLand.value?'补充地块定位':'新建地块',growth:'新增生长记录',environment:'记录田间环境',confirm:'人工确认并安排任务',feedback:'填写执行结果'}[dialog.value]||''))
function message(e:unknown){return e instanceof Error?e.message:'请求失败，请重试'}
async function loadLands(){const r=await api<{items:RecordRow[]}>('/records/lands?size=200');lands.value=r.items}
async function refresh(){if(!plotId.value)return;const id=plotId.value;busy.value=true;try{const r=await api<Flow>(`/plots/${id}/flow`);if(plotId.value!==id)return;flow.value=r;if(!r.growth.some(g=>g.id===analysis.growth_id))analysis.growth_id=r.growth.at(-1)?.id;if(selected.value)selected.value=r.jobs.find(j=>j.id===selected.value?.id);else selected.value=r.jobs[0]}catch(e){error.value=message(e)}finally{if(plotId.value===id)busy.value=false}}
watch(plotId,()=>{flow.value=undefined;weather.value=undefined;weatherError.value='';selected.value=undefined;analysis.image='';analysis.question='';analysis.growth_id=undefined;error.value='';if(fileInput.value)fileInput.value.value='';refresh()})
watch(()=>analysis.growth_id,()=>{analysis.image='';analysis.question='';if(fileInput.value)fileInput.value.value=''})
onMounted(async()=>{try{await loadLands();const requested=Number(route.query.plot_id);plotId.value=lands.value.find(l=>l.id===requested)?.id||lands.value[0]?.id}catch(e){error.value=message(e)}})
async function queryWeather(){if(!plotId.value)return;const id=plotId.value;weatherBusy.value=true;weatherError.value='';try{const r=await api<Weather>(`/plots/${id}/weather`);if(id===plotId.value)weather.value=r}catch(e){if(id===plotId.value)weatherError.value=message(e)}finally{weatherBusy.value=false}}
function open(kind:string){error.value='';editingLand.value=undefined;if(kind==='land')Object.assign(land,{title:'',crop:'',latitude:undefined,longitude:undefined});if(kind==='growth')Object.assign(growth,{title:'',crop:flow.value?.land.data.crop||'',variety:'',sow_date:today(),stage:'营养生长期',harvest_date:'',height:undefined,note:''});if(kind==='environment')Object.assign(environment,{temperature:undefined,humidity:undefined,soil:undefined,source:'人工记录',note:''});if(kind==='confirm')Object.assign(confirmation,{title:`${selected.value?.result.plot||''}现场巡检`,assignee:props.user.name,date:today(),note:''});dialog.value=kind}
function editLocation(){if(!flow.value)return;editingLand.value=flow.value.land;Object.assign(land,{title:flow.value.land.title,crop:String(flow.value.land.data.crop||''),latitude:flow.value.land.data.latitude,longitude:flow.value.land.data.longitude});dialog.value='land'}
async function save(){if(!await formRef.value?.validate().catch(()=>false))return;if(!flow.value&&dialog.value!=='land')return;saving.value=true;error.value='';try{
if(dialog.value==='land'){const data={...(editingLand.value?.data||{}),crop:land.crop,latitude:land.latitude,longitude:land.longitude};const row=await api<RecordRow>(`/records/lands${editingLand.value?'/'+editingLand.value.id:''}`,{method:editingLand.value?'PUT':'POST',body:JSON.stringify({title:land.title,data,version:editingLand.value?.version})});await loadLands();if(plotId.value===row.id)await refresh();else plotId.value=row.id;weather.value=undefined}
else if(dialog.value==='growth'){if(growth.harvest_date&&growth.harvest_date<growth.sow_date){ElMessage.warning('预计采收日期不能早于播种日期');return}const {title,...data}=growth;await post('/records/growth',{title,data:{...data,plot_id:plotId.value,plot:flow.value!.land.title}});await refresh()}
else if(dialog.value==='environment'){await post('/records/environment',{title:`${flow.value!.land.title}环境观察 ${today()}`,data:{...environment,plot_id:plotId.value,plot:flow.value!.land.title}});await refresh()}
else if(dialog.value==='confirm'&&selected.value){await post(`/ai/jobs/${selected.value.id}/confirm`,confirmation);await refresh();activeTab.value='tasks'}
else if(dialog.value==='feedback'&&editingTask.value){await updateTask(editingTask.value,'已完成',feedback.note);await refresh()}
dialog.value='';ElMessage.success('已保存')
}catch(e){error.value=message(e);ElMessage.error(error.value)}finally{saving.value=false}}
function chooseFile(event:Event){const f=(event.target as HTMLInputElement).files?.[0];if(!f)return;analysis.image='';if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>10*1024*1024){ElMessage.error('请选择不超过10 MB的JPG、PNG或WebP');return}const selectedPlot=plotId.value,selectedGrowth=analysis.growth_id;const reader=new FileReader();reader.onload=()=>{if(selectedPlot===plotId.value&&selectedGrowth===analysis.growth_id){analysis.image=String(reader.result);analysisRef.value?.validateField('image').catch(()=>false)}};reader.onerror=()=>ElMessage.error('照片读取失败');reader.readAsDataURL(f)}
async function analyze(){if(!await analysisRef.value?.validate().catch(()=>false))return;saving.value=true;error.value='';try{selected.value=await post<AIJob>('/ai/analyze',{kind:'diagnosis',question:analysis.question,plot_id:plotId.value,growth_id:analysis.growth_id,image:analysis.image});await refresh();ElMessage.success('分析完成，请人工核对后安排任务')}catch(e){error.value=message(e);await refresh()}finally{saving.value=false}}
async function reject(){if(!selected.value)return;try{await ElMessageBox.confirm('驳回后不生成任务，仍保留分析记录。','驳回建议');saving.value=true;await post(`/ai/jobs/${selected.value.id}/reject`,{});await refresh();ElMessage.success('已驳回')}catch(e){if(e instanceof Error)ElMessage.error(e.message)}finally{saving.value=false}}
async function updateTask(row:RecordRow,status:string,note?:string){await api(`/records/tasks/${row.id}`,{method:'PUT',body:JSON.stringify({title:row.title,status,version:row.version,data:{...row.data,note:note??row.data.note}})})}
async function startTask(row:RecordRow){saving.value=true;try{await updateTask(row,'进行中');await refresh();ElMessage.success('任务已开始')}catch(e){ElMessage.error(message(e))}finally{saving.value=false}}
function complete(row:RecordRow){editingTask.value=row;feedback.note='';dialog.value='feedback'}
function viewTaskAnalysis(row:RecordRow){selected.value=flow.value?.jobs.find(j=>j.id===row.data.ai_job_id);activeTab.value='ai'}
async function photo(){if(!selected.value?.result.photo_id)return;try{await download(`/files/${selected.value.result.photo_id}`,'田间分析照片')}catch(e){ElMessage.error(message(e))}}
function text(v:unknown){return v===undefined||v===null||v===''?'—':String(v)}
</script>
<template>
<div class="page-title"><div><h1>种植管理流程</h1><p>地块 → 生长记录 → 天气环境 → 照片分析 → 人工确认 → 农事任务</p></div><el-button type="primary" @click="open('land')" :disabled="saving">新建地块</el-button></div>
<section class="panel"><div class="toolbar"><el-select v-model="plotId" placeholder="选择地块 / 温室" style="width:300px" :disabled="saving"><el-option v-for="r in lands" :key="r.id" :label="r.title+(r.demo?'（演示）':'')" :value="r.id"/></el-select><el-button @click="refresh" :loading="busy" :disabled="!plotId||saving">刷新档案</el-button><el-button @click="editLocation" :disabled="!flow||saving">补充地块定位</el-button></div><el-steps :active="progress" finish-status="success" align-center><el-step v-for="s in ['地块建档','生长记录','天气与环境','图片分析','人工确认','任务反馈']" :key="s" :title="s"/></el-steps></section>
<el-alert v-if="error" :title="error" type="error" :closable="false" style="margin-bottom:16px"/>
<el-empty v-if="!flow" :description="busy?'正在读取地块档案':'先新建或选择地块'"/>
<template v-else><div class="metrics"><div class="metric"><div class="metric-label">当前地块</div><strong>{{flow.land.title}}</strong><p class="muted">{{flow.land.demo?'演示地块':'用户建档'}} · {{text(flow.land.data.crop)}}</p></div><div class="metric"><div class="metric-label">生长记录</div><div class="metric-value">{{flow.growth.length}}</div></div><div class="metric"><div class="metric-label">待人工确认</div><div class="metric-value">{{flow.jobs.filter(j=>j.status==='待确认').length}}</div></div><div class="metric"><div class="metric-label">已完成任务</div><div class="metric-value">{{flow.tasks.filter(t=>t.status==='已完成').length}} / {{flow.tasks.length}}</div></div></div>
<section class="panel"><el-tabs v-model="activeTab">
<el-tab-pane name="growth" label="生长记录"><div class="toolbar"><el-button type="primary" @click="open('growth')" :disabled="saving">新增生长记录</el-button><span class="muted">按种植批次记录实际生长阶段；预计采收日期由用户填写。</span></div><el-table :data="flow.growth" empty-text="先新增生长记录，后续照片分析会关联该记录"><el-table-column prop="title" label="批次 / 记录" min-width="180"/><el-table-column label="作物 / 品种"><template #default="{row}">{{text(row.data.crop)}} / {{text(row.data.variety)}}</template></el-table-column><el-table-column label="生长阶段"><template #default="{row}">{{row.data.stage}}</template></el-table-column><el-table-column label="播种 / 定植日期"><template #default="{row}">{{row.data.sow_date}}</template></el-table-column><el-table-column label="预计采收"><template #default="{row}">{{text(row.data.harvest_date)}}</template></el-table-column><el-table-column label="观察记录" min-width="180"><template #default="{row}">{{text(row.data.note)}}</template></el-table-column></el-table></el-tab-pane>
<el-tab-pane name="environment" label="天气与环境"><div class="toolbar"><el-button @click="queryWeather" :loading="weatherBusy">按地块查询天气</el-button><el-button type="primary" @click="open('environment')" :disabled="saving">记录田间环境</el-button><span class="muted">经纬度：{{text(flow.land.data.latitude)}}，{{text(flow.land.data.longitude)}}</span></div><el-alert v-if="weatherError" :title="weatherError" type="warning" :closable="false"/><el-descriptions v-if="weather" :column="3" border><el-descriptions-item label="室外温度">{{weather.current.temperature_2m}} ℃</el-descriptions-item><el-descriptions-item label="室外湿度">{{weather.current.relative_humidity_2m}} %</el-descriptions-item><el-descriptions-item label="风速">{{weather.current.wind_speed_10m}} km/h</el-descriptions-item><el-descriptions-item label="降水">{{weather.current.precipitation}} mm</el-descriptions-item><el-descriptions-item label="天气时间">{{weather.current.time}}</el-descriptions-item><el-descriptions-item label="来源">{{weather.source}} · {{weather.cached?'Redis缓存':'实时请求'}}</el-descriptions-item></el-descriptions><p class="muted">室外天气与田间实测分开记录；AI分析时会重新读取天气并保留当时的资料快照。</p><el-table :data="flow.environment" empty-text="尚无关联的田间环境记录"><el-table-column prop="created_at" label="记录时间" min-width="180"/><el-table-column label="温度℃"><template #default="{row}">{{row.data.temperature}}</template></el-table-column><el-table-column label="空气湿度%"><template #default="{row}">{{row.data.humidity}}</template></el-table-column><el-table-column label="土壤湿度%"><template #default="{row}">{{row.data.soil}}</template></el-table-column><el-table-column label="数据来源"><template #default="{row}">{{row.data.source}}</template></el-table-column><el-table-column label="说明"><template #default="{row}">{{text(row.data.note)}}</template></el-table-column></el-table></el-tab-pane>
<el-tab-pane name="ai" label="AI分析与确认"><div class="columns"><div><el-form ref="analysisRef" :model="analysis" :rules="analysisRules" label-position="top"><el-form-item label="关联生长记录" prop="growth_id"><el-select v-model="analysis.growth_id" :disabled="saving" placeholder="选择本次照片所属批次"><el-option v-for="g in flow.growth" :key="g.id" :value="g.id" :label="g.title+' · '+text(g.data.stage)"/></el-select></el-form-item><p class="muted">作物：{{text(currentGrowth?.data.crop)}} · 阶段：{{text(currentGrowth?.data.stage)}}<br/>最近田间环境：{{text(latestEnvironment?.data.source)}}，{{text(latestEnvironment?.data.temperature)}}℃ / 空气湿度{{text(latestEnvironment?.data.humidity)}}%</p><el-form-item label="田间照片" prop="image"><input ref="fileInput" type="file" accept="image/png,image/jpeg,image/webp" :disabled="saving" @change="chooseFile"/></el-form-item><img v-if="analysis.image" :src="analysis.image" class="image-preview" alt="本次田间照片预览"/><el-form-item label="异常描述" prop="question"><el-input v-model="analysis.question" type="textarea" :rows="4" maxlength="4000" show-word-limit :disabled="saving" placeholder="例如：近两天叶片发黄，主要在下部叶片，尚未施药"/></el-form-item><el-button type="primary" :loading="saving" @click="analyze">提交照片与地块资料分析</el-button></el-form><p class="muted">照片及所选地块资料会发送给配置的千问服务。分析仅为初筛，确认后生成现场巡检任务。</p></div><div><h3>分析结果</h3><template v-if="selected"><el-tag>{{selected.status}}</el-tag><p class="muted">分析 #{{selected.id}} · {{selected.result.plot}} · {{selected.result.crop}}<br/>{{selected.created_at}}</p><el-button v-if="selected.result.photo_id" @click="photo">下载本次分析照片</el-button><el-collapse style="margin:12px 0"><el-collapse-item title="查看分析时的资料快照"><pre class="prewrap">{{JSON.stringify({land:selected.result.land,records:selected.result.records,weather:selected.result.weather},null,2)}}</pre></el-collapse-item></el-collapse><el-steps direction="vertical" :active="selected.steps.length" finish-status="success"><el-step v-for="s in selected.steps" :key="s" :title="s"/></el-steps><div class="prewrap" style="margin-top:15px">{{selected.result.answer}}</div><div class="toolbar" style="margin-top:20px" v-if="selected.status==='待确认'"><el-button type="primary" :disabled="saving" @click="open('confirm')">人工确认并安排任务</el-button><el-button type="danger" :disabled="saving" @click="reject">驳回建议</el-button></div><el-alert v-if="selected.task_id" :title="`已生成农事任务 #${selected.task_id}，在任务反馈页查看进度。`" type="success" :closable="false"/></template><el-empty v-else description="提交照片后显示真实模型回答"/></div></div><h3>本地块分析历史</h3><el-table :data="flow.jobs" @row-click="selected=$event"><el-table-column prop="id" label="编号" width="75"/><el-table-column prop="question" label="问题" show-overflow-tooltip/><el-table-column prop="status" label="状态"/><el-table-column prop="task_id" label="关联任务"/></el-table></el-tab-pane>
<el-tab-pane name="tasks" label="农事任务与反馈"><el-table :data="flow.tasks" empty-text="确认AI建议后生成关联任务"><el-table-column prop="title" label="任务" min-width="180"/><el-table-column label="执行人"><template #default="{row}">{{text(row.data.assignee)}}</template></el-table-column><el-table-column label="计划日期"><template #default="{row}">{{text(row.data.date)}}</template></el-table-column><el-table-column prop="status" label="状态"/><el-table-column label="执行结果 / 确认意见" min-width="220"><template #default="{row}">{{text(row.data.note)}}</template></el-table-column><el-table-column label="操作" min-width="220"><template #default="{row}"><el-button v-if="row.data.ai_job_id" link @click="viewTaskAnalysis(row)">查看分析</el-button><el-button v-if="row.status==='待处理'" link type="primary" :disabled="saving" @click="startTask(row)">开始任务</el-button><el-button v-if="['待处理','进行中'].includes(row.status)" link type="success" :disabled="saving" @click="complete(row)">完成反馈</el-button></template></el-table-column></el-table></el-tab-pane>
</el-tabs></section></template>
<el-dialog :model-value="!!dialog" @close="dialog=''" :title="dialogTitle" width="600px" destroy-on-close :close-on-click-modal="!saving" :show-close="!saving"><el-form ref="formRef" :model="model" :rules="rules" label-position="top">
<template v-if="dialog==='land'"><el-form-item label="地块名称" prop="title"><el-input v-model="land.title" maxlength="180" placeholder="例如：东区番茄温室" :disabled="!!editingLand"/></el-form-item><el-form-item label="作物" prop="crop"><el-input v-model="land.crop" maxlength="64" placeholder="例如：番茄"/></el-form-item><el-form-item label="纬度" prop="latitude"><el-input-number v-model="land.latitude" :min="18" :max="54" :precision="5" placeholder="例如30.27"/></el-form-item><el-form-item label="经度" prop="longitude"><el-input-number v-model="land.longitude" :min="73" :max="135" :precision="5" placeholder="例如120.15"/></el-form-item><p class="muted">填写地块实际经纬度。边界可在GIS地块资源页面绘制。</p></template>
<template v-else-if="dialog==='growth'"><el-form-item label="种植批次 / 记录名称" prop="title"><el-input v-model="growth.title" maxlength="180" placeholder="例如：番茄秋季批次第1次观察"/></el-form-item><el-form-item label="作物" prop="crop"><el-input v-model="growth.crop" maxlength="64" placeholder="例如：番茄"/></el-form-item><el-form-item label="品种"><el-input v-model="growth.variety" placeholder="例如：粉果番茄，未知可留空"/></el-form-item><el-form-item label="播种 / 定植日期" prop="sow_date"><el-date-picker v-model="growth.sow_date" value-format="YYYY-MM-DD" placeholder="选择实际播种日期"/></el-form-item><el-form-item label="实际生长阶段" prop="stage"><el-select v-model="growth.stage"><el-option v-for="s in ['育苗期','营养生长期','开花结果期','收获期','其他']" :key="s" :value="s" :label="s"/></el-select></el-form-item><el-form-item label="预计采收日期"><el-date-picker v-model="growth.harvest_date" value-format="YYYY-MM-DD" placeholder="未知可留空"/></el-form-item><el-form-item label="株高（cm）"><el-input-number v-model="growth.height" :min="0" placeholder="例如86"/></el-form-item><el-form-item label="观察记录"><el-input v-model="growth.note" type="textarea" placeholder="例如：下部叶片轻微发黄，记录叶片范围"/></el-form-item></template>
<template v-else-if="dialog==='environment'"><el-form-item label="空气温度（℃）" prop="temperature"><el-input-number v-model="environment.temperature" :min="-50" :max="70" :precision="1" placeholder="例如26.5"/></el-form-item><el-form-item label="空气湿度（%）" prop="humidity"><el-input-number v-model="environment.humidity" :min="0" :max="100" placeholder="例如68"/></el-form-item><el-form-item label="土壤湿度（%）" prop="soil"><el-input-number v-model="environment.soil" :min="0" :max="100" placeholder="例如45"/></el-form-item><el-form-item label="数据来源" prop="source"><el-select v-model="environment.source"><el-option v-for="s in ['人工记录','模拟器','传感器']" :key="s" :value="s" :label="s"/></el-select></el-form-item><el-form-item label="测量说明"><el-input v-model="environment.note" type="textarea" placeholder="例如：手持仪表测量，土壤探头埋深10cm；模拟数据请注明"/></el-form-item></template>
<template v-else-if="dialog==='confirm'"><el-alert title="请人工核对原始照片和AI建议，安排现场复核，不自动施药。" :closable="false"/><el-form-item label="任务名称" prop="title"><el-input v-model="confirmation.title" maxlength="180" placeholder="例如：东区叶片异常现场巡检"/></el-form-item><el-form-item label="执行人" prop="assignee"><el-input v-model="confirmation.assignee" maxlength="64" placeholder="例如：张师傅"/></el-form-item><el-form-item label="计划日期" prop="date"><el-date-picker v-model="confirmation.date" value-format="YYYY-MM-DD" placeholder="选择巡检日期"/></el-form-item><el-form-item label="人工确认意见 / 任务要求" prop="note"><el-input v-model="confirmation.note" type="textarea" :rows="4" maxlength="6000" placeholder="例如：先检查叶背虫体和根区积水，记录范围后联系农技员"/></el-form-item></template>
<template v-else><el-form-item label="实际执行结果" prop="note"><el-input v-model="feedback.note" type="textarea" :rows="5" maxlength="6000" placeholder="填写现场观察、实际操作、处理结果及后续观察安排"/></el-form-item></template>
<el-alert v-if="error" :title="error" type="error" :closable="false"/></el-form><template #footer><el-button @click="dialog=''" :disabled="saving">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog>
</template>
